def count_awesome_substrings(s):
    n = len(s)
    count = 0

    for i in range(n):
        ones_count = 0
        for j in range(i, n):
            if s[j] == '1':
                ones_count += 1
            if ones_count > 0 and (j - i + 1) % ones_count == 0:
                count += 1
    return count

# Read input from stdin
s = input().strip()

# Output the result
print(count_awesome_substrings(s))
